import { LogoCloud } from "../components/logo-cloud/two/logo-cloud";

export default function Page() {
	return (
		<div className="min-h-screen w-full place-content-center px-4">
			<section className="relative">
				<h2 className="mb-6 text-center font-medium text-lg text-muted-foreground tracking-tight md:text-2xl">
					Companies we{" "}
					<span className="font-semibold text-primary">collaborate</span> with.
				</h2>
				<div className="relative mx-auto max-w-3xl *:border-y-0">
					<div className="pointer-events-none absolute -top-px left-1/2 h-px w-screen -translate-x-1/2 bg-border" />
					<LogoCloud />
					<div className="pointer-events-none absolute -bottom-px left-1/2 h-px w-screen -translate-x-1/2 bg-border" />
				</div>
			</section>
		</div>
	);
}

import type { ElementType, SVGProps } from "react";
import {
	ClaudeAIWordmark as ClaudeLogo,
	ClerkWordmark as ClerkLogo,
	GithubWordmark as GithubLogo,
	IBMWordmark as IBMLogo,
	NextjsWordmark as NextjsLogo,
	OpenAIWordmark as OpenAILogo,
	ResendWordmark as ResendLogo,
	VercelWordmark as VercelLogo,
} from "love-ui/logos";

import { cn } from "@/lib/utils";
import { DecorIcon } from "./decor-icon";

type LogoComponent = ElementType<SVGProps<SVGSVGElement>>;

type Logo = {
	Component: LogoComponent;
	alt: string;
	className?: string;
};

function LogoAsset({ logo, className }: { logo: Logo; className: string }) {
	const Component = logo.Component;

	return (
		<Component
			aria-label={logo.alt}
			className={cn(className, logo.className)}
			role="img"
		/>
	);
}

export function LogoCloud() {
	return (
		<div className="grid grid-cols-2 border md:grid-cols-4">
			<LogoCard
				className="relative border-r border-b bg-secondary dark:bg-secondary/30"
				logo={{ Component: NextjsLogo, alt: "Next.js Logo" }}
			>
				<DecorIcon className="z-10" position="bottom-right" />
			</LogoCard>

			<LogoCard
				className="border-b md:border-r"
				logo={{ Component: ResendLogo, alt: "Resend Logo" }}
			/>

			<LogoCard
				className="relative border-r border-b md:bg-secondary dark:md:bg-secondary/30"
				logo={{ Component: GithubLogo, alt: "GitHub Logo" }}
			>
				<DecorIcon className="z-10" position="bottom-right" />
				<DecorIcon className="z-10 hidden md:block" position="bottom-left" />
			</LogoCard>

			<LogoCard
				className="relative border-b bg-secondary md:bg-background dark:bg-secondary/30 md:dark:bg-background"
				logo={{ Component: OpenAILogo, alt: "OpenAI Logo" }}
			/>

			<LogoCard
				className="relative border-r border-b bg-secondary md:border-b-0 md:bg-background dark:bg-secondary/30 md:dark:bg-background"
				logo={{ Component: IBMLogo, alt: "IBM Logo" }}
			>
				<DecorIcon className="z-10 md:hidden" position="bottom-right" />
			</LogoCard>

			<LogoCard
				className="border-b bg-background md:border-r md:border-b-0 md:bg-secondary dark:md:bg-secondary/30"
				logo={{ Component: ClerkLogo, alt: "Clerk Logo" }}
			/>

			<LogoCard
				className="border-r"
				logo={{ Component: ClaudeLogo, alt: "Claude AI Logo" }}
			/>

			<LogoCard
				className="bg-secondary dark:bg-secondary/30"
				logo={{ Component: VercelLogo, alt: "Vercel Logo" }}
			/>
		</div>
	);
}

type LogoCardProps = React.ComponentProps<"div"> & {
	logo: Logo;
};

function LogoCard({ logo, className, children, ...props }: LogoCardProps) {
	return (
		<div
			className={cn(
				"flex min-h-28 items-center justify-center bg-background px-4 py-8 md:p-8",
				className
			)}
			{...props}
		>
			<LogoAsset
				className="pointer-events-none h-9 w-36 select-none text-foreground md:h-11 md:w-44"
				logo={logo}
			/>
			{children}
		</div>
	);
}

import { cn } from "@/lib/utils";
import { cva, type VariantProps } from "class-variance-authority";

const DecorIconVariants = cva(
	"pointer-events-none absolute z-1 size-5 shrink-0 stroke-1 stroke-muted-foreground",
	{
		variants: {
			position: {
				"top-left":
					"top-0 left-0 -translate-x-[calc(50%+0.5px)] -translate-y-[calc(50%+0.5px)]",
				"top-right":
					"top-0 right-0 translate-x-[calc(50%+0.5px)] -translate-y-[calc(50%+0.5px)]",
				"bottom-right":
					"right-0 bottom-0 translate-x-[calc(50%+0.5px)] translate-y-[calc(50%+0.5px)]",
				"bottom-left":
					"bottom-0 left-0 -translate-x-[calc(50%+0.5px)] translate-y-[calc(50%+0.5px)]",
			},
		},
		defaultVariants: {
			position: "top-left",
		},
	}
);

type DecorIconProps = React.ComponentProps<"svg"> &
	VariantProps<typeof DecorIconVariants>;

export function DecorIcon({ position, className, ...props }: DecorIconProps) {
	return (
		<svg
			aria-hidden="true"
			className={cn(DecorIconVariants({ position, className }))}
			fill="none"
			stroke="currentColor"
			strokeLinecap="round"
			strokeLinejoin="round"
			viewBox="0 0 24 24"
			xmlns="http://www.w3.org/2000/svg"
			{...props}
		>
			<path d="M5 12h14" />
			<path d="M12 5v14" />
		</svg>
	);
}
